namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        var validationFailure = ValidatePresence(principal, resource, request)
            ?? ValidateIdentity(principal!, resource!)
            ?? ValidateRequest(principal!, resource!, request!);

        if (validationFailure is not null)
            return validationFailure;

        var facts = GatherAuthorizationFacts(principal!, resource!, request!, delegations);
        return EvaluateAccess(resource!, request!, facts);
    }

    private static AccessDecision? ValidatePresence(Principal? principal, Resource? resource, AccessRequest? request)
    {
        return principal is null || resource is null || request is null
            ? new AccessDecision(false, "missing-context", true)
            : null;
    }

    private static AccessDecision? ValidateIdentity(Principal principal, Resource resource)
    {
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return new AccessDecision(false, "invalid-identity", true);
        if (principal.Suspended)
            return new AccessDecision(false, "principal-suspended", true);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return new AccessDecision(false, "tenant-mismatch", true);

        return null;
    }

    private static AccessDecision? ValidateRequest(Principal principal, Resource resource, AccessRequest request)
    {
        if (resource.Locked && request.Action != "read")
            return new AccessDecision(false, "resource-locked", true);
        if (request.MinuteOfDay is < 0 or > 1439)
            return new AccessDecision(false, "invalid-time", true);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return new AccessDecision(false, "challenge-required", true);

        return null;
    }

    private static AuthorizationFacts GatherAuthorizationFacts(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        return new AuthorizationFacts(
            principal.Roles.Contains("administrator"),
            principal.Roles.Contains("operator"),
            principal.Roles.Contains("auditor"),
            principal.Id == resource.OwnerId,
            delegations.HasDelegation(principal.Id, resource.Id, request.Action));
    }

    private static AccessDecision EvaluateAccess(Resource resource, AccessRequest request, AuthorizationFacts facts)
    {
        if (request.BreakGlass)
            return EvaluateBreakGlass(request, facts);

        var restrictionFailure = EvaluateRestrictions(resource, request);
        if (restrictionFailure is not null)
            return restrictionFailure;

        var actionFailure = EvaluateAction(request.Action, facts);
        if (actionFailure is not null)
            return actionFailure;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            facts.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static AccessDecision EvaluateBreakGlass(AccessRequest request, AuthorizationFacts facts)
    {
        if (!facts.Administrator || !request.StrongAuthentication)
            return new AccessDecision(false, "invalid-break-glass", true);

        return new AccessDecision(true, "break-glass", true);
    }

    private static AccessDecision? EvaluateRestrictions(Resource resource, AccessRequest request)
    {
        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return new AccessDecision(false, "strong-authentication-required", true);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return new AccessDecision(false, "trusted-network-required", true);

        return null;
    }

    private static AccessDecision? EvaluateAction(string action, AuthorizationFacts facts)
    {
        return action switch
        {
            "delete" => EvaluateDelete(facts),
            "write" => EvaluateWrite(facts),
            "read" => EvaluateRead(facts),
            _ => new AccessDecision(false, "unknown-action", true)
        };
    }

    private static AccessDecision? EvaluateDelete(AuthorizationFacts facts)
    {
        return facts.Administrator
            ? null
            : new AccessDecision(false, "administrator-required", true);
    }

    private static AccessDecision? EvaluateWrite(AuthorizationFacts facts)
    {
        if (facts.Administrator || facts.Operator || facts.Owner || facts.Delegated)
            return null;

        return new AccessDecision(false, "write-not-authorised", true);
    }

    private static AccessDecision? EvaluateRead(AuthorizationFacts facts)
    {
        if (facts.Administrator || facts.Operator || facts.Auditor || facts.Owner || facts.Delegated)
            return null;

        return new AccessDecision(false, "read-not-authorised", false);
    }

    private readonly record struct AuthorizationFacts(
        bool Administrator,
        bool Operator,
        bool Auditor,
        bool Owner,
        bool Delegated);
}
